-- AA Tuition Portal v10.21.0
-- Textbook-aligned exam-board curricula: AQA Biology, AQA/Edexcel Chemistry, OCR Further Maths.
-- OCR Biology and OCR Chemistry already loaded by earlier migrations are preserved.
-- Safe to run more than once.

alter table public.curriculum_topics add column if not exists exam_board text;

alter table public.student_courses drop constraint if exists student_courses_course_check;
alter table public.student_courses add constraint student_courses_course_check check (course in ('GCSE Mathematics','GCSE Combined Science','A-level Mathematics','A-level Further Mathematics','A-level Chemistry','A-level Physics','A-level Biology'));

alter table public.curriculum_topics drop constraint if exists curriculum_topics_course_check;
alter table public.curriculum_topics add constraint curriculum_topics_course_check check (course in ('GCSE Combined Science','A-level Mathematics','A-level Further Mathematics','A-level Chemistry','A-level Physics','A-level Biology'));

-- Tag legacy board-specific rows where needed.
update public.curriculum_topics set exam_board='OCR' where course='A-level Chemistry' and exam_board is null;
update public.curriculum_topics set exam_board='OCR' where course='A-level Biology' and exam_board is null;
update public.curriculum_topics set exam_board='AQA' where course='A-level Physics' and exam_board is null;

-- Replace only the curricula introduced/updated in this migration.
delete from public.curriculum_topics where course='A-level Biology' and exam_board='AQA';
delete from public.curriculum_topics where course='A-level Chemistry' and exam_board in ('AQA','Edexcel');
delete from public.curriculum_topics where course='A-level Further Mathematics' and exam_board='OCR';

